import fs from "fs";
import path from "path";

const QR_BASE64 = "";

export function getQrImageBuffer(): Buffer {
  try {
    const filePath = path.join(process.cwd(), "src", "assets", "ilai-upi-qr.png");
    if (fs.existsSync(filePath)) {
      return fs.readFileSync(filePath);
    }
  } catch (e) {
    // Fallback to embedded base64
  }
  return Buffer.from(QR_BASE64, "base64");
}
